                        <button className="text-indigo-500 text-xs font-bold hover:underline">View All</button>
                    </div>
                    <div className="space-y-4">
                        {MOCK_REVIEWS.slice(0, 4).map((review) => (
                            <div key={review.id} className="flex items-center gap-4">
