              <p className="text-gray-500 dark:text-gray-400 text-lg">No listings found matching your criteria.</p>
              <button 
                onClick={clearFilters}
                className="mt-4 text-primary font-medium hover:underline"
              >
                  Clear all filters
              </button>
          </div>
      )}
    </div>
  );
};

