            category: data.category,
            upvotes: 0,
            downvotes: 0,
            commentCount: 0,
            timestamp: 'Just now',
            userVote: null,
            comments: []
        };

        setThreads([newThread, ...threads]);
        setIsCreateModalOpen(false);
    };

    const stripHtml = (html: string) => {
        const tmp = document.createElement("DIV");
        tmp.innerHTML = html;
        return tmp.textContent || tmp.innerText || "";
