                                  </div>
                                  <div className="text-left">
                                      <div className="font-bold text-dark dark:text-white text-sm">{opt.label} Pack</div>
                                      {opt.popular && <span className="text-[10px] text-green-500 font-bold uppercase">Best Value</span>}
