                      <button onClick={() => setIsAdModalOpen(false)} className="text-gray-400 hover:text-dark dark:hover:text-white">
                          <X size={20} />
                      </button>
                  </div>
                  <form onSubmit={handleSaveAd} className="p-6 space-y-4">
                      <div>
                          <label className="block text-sm font-bold text-gray-700 dark:text-gray-300 mb-1">Placement Name</label>
                          <input name="name" defaultValue={currentAd.name} required className="w-full px-4 py-2 rounded-lg bg-gray-50 dark:bg-slate-800 border border-gray-200 dark:border-gray-700 focus:border-primary focus:outline-none dark:text-white" placeholder="e.g. Summer Sale Banner" />
                      </div>

                      <div className="grid grid-cols-2 gap-4">
                          <div>
                              <label className="block text-sm font-bold text-gray-700 dark:text-gray-300 mb-1">Status</label>
                              <select name="status" defaultValue={currentAd.status} className="w-full px-4 py-2 rounded-lg bg-gray-50 dark:bg-slate-800 border border-gray-200 dark:border-gray-700 focus:border-primary focus:outline-none dark:text-white">
                                  <option value="active">Active</option>
                                  <option value="paused">Paused</option>
                              </select>
                          </div>
                          <div>
                              <label className="block text-sm font-bold text-gray-700 dark:text-gray-300 mb-1">Location</label>
                              <select name="location" defaultValue={currentAd.location} className="w-full px-4 py-2 rounded-lg bg-gray-50 dark:bg-slate-800 border border-gray-200 dark:border-gray-700 focus:border-primary focus:outline-none dark:text-white">
                                  <option>Homepage Banner</option>
                                  <option>Listing Sidebar</option>
                                  <option>Search Results Top</option>
                              </select>
                          </div>
                      </div>

                      <div>
                          <label className="block text-sm font-bold text-gray-700 dark:text-gray-300 mb-1">Ad Image</label>
                          <div className="border-2 border-dashed border-gray-200 dark:border-gray-700 rounded-lg p-6 text-center hover:border-primary transition-colors bg-gray-50 dark:bg-slate-800/50 cursor-pointer">
                              <UploadCloud className="mx-auto h-8 w-8 text-gray-400 mb-2" />
                              <p className="text-xs text-gray-500">Click to upload banner image</p>
                          </div>
                      </div>

                      <div>
                          <label className="block text-sm font-bold text-gray-700 dark:text-gray-300 mb-1">Destination URL</label>
                          <input name="destinationUrl" defaultValue={currentAd.destinationUrl} required className="w-full px-4 py-2 rounded-lg bg-gray-50 dark:bg-slate-800 border border-gray-200 dark:border-gray-700 focus:border-primary focus:outline-none dark:text-white" placeholder="https://..." />
                      </div>

                      <div className="grid grid-cols-2 gap-4">
                          <div>
                              <label className="block text-sm font-bold text-gray-700 dark:text-gray-300 mb-1">Start Date</label>
                              <input type="date" name="startDate" defaultValue={currentAd.startDate?.split('T')[0]} required className="w-full px-4 py-2 rounded-lg bg-gray-50 dark:bg-slate-800 border border-gray-200 dark:border-gray-700 focus:border-primary focus:outline-none dark:text-white" />
                          </div>
                          <div>
                              <label className="block text-sm font-bold text-gray-700 dark:text-gray-300 mb-1">End Date</label>
                              <input type="date" name="endDate" defaultValue={currentAd.endDate?.split('T')[0]} required className="w-full px-4 py-2 rounded-lg bg-gray-50 dark:bg-slate-800 border border-gray-200 dark:border-gray-700 focus:border-primary focus:outline-none dark:text-white" />
                          </div>
                      </div>

                      <div>
                          <label className="block text-sm font-bold text-gray-700 dark:text-gray-300 mb-1">Target Category</label>
                          <select name="category" defaultValue={currentAd.targeting?.category} className="w-full px-4 py-2 rounded-lg bg-gray-50 dark:bg-slate-800 border border-gray-200 dark:border-gray-700 focus:border-primary focus:outline-none dark:text-white">
                              <option value="">All Categories</option>
                              {CATEGORIES.map(cat => (
                                  <option key={cat.id} value={cat.name}>{cat.name}</option>
                              ))}
                          </select>
                      </div>

                      <div className="flex justify-end gap-3 mt-4 pt-4 border-t border-gray-100 dark:border-gray-800">
                          <button type="button" onClick={() => setIsAdModalOpen(false)} className="px-4 py-2 rounded-lg font-bold text-gray-500 hover:bg-gray-100 dark:hover:bg-gray-800 transition-colors">Cancel</button>
                          <button type="submit" className="bg-primary hover:bg-red-600 text-white px-6 py-2 rounded-lg font-bold shadow-md transition-colors">Save Campaign</button>
                      </div>
                  </form>
              </div>
          </div>
      )}

    </div>
  );
};

