            </div>
        </div>
      </div>

      {/* Related Businesses / You Might Also Like */}
      {relatedBusinesses.length > 0 && (
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 mt-12 border-t border-gray-100 dark:border-gray-800 pt-12">
