export type Permission = 
  | 'view_admin_dashboard'
  | 'manage_users' 
  | 'manage_listings' 
  | 'manage_content' 
  | 'manage_settings' 
  | 'manage_marketing'
  | 'manage_orders'
  | 'create_review';

export interface Business {
  id: string;
  name: string;
  category: string;
  location: string;
  image: string;
  logo?: string; // Added logo field
  rating: number;
  reviewCount: number;
  priceRange: string;
  description: string;
  isOpen: boolean;
  tags: string[];
  phone: string;
  email: string;
  instagramHandle?: string;
  whatsapp?: string;
  viewCount: number;
  ownerId?: string;
  isPromoted?: boolean;
  isFeatured?: boolean; // Editor's Pick
  credits: number; // Added credit field specific to the business profile
  createdAt?: string;
  lastActiveAt?: string;
  verificationStatus?: 'pending' | 'verified' | 'rejected';
  status: 'active' | 'inactive'; // Active/Inactive status
}

export interface Category {
  id: string;
  name: string;
  icon: string;
  count: number;
}

export interface Review {
  id: string;
  businessId: string;
  userId: string;
  userName: string;
  userImage: string;
  rating: number; // 1-5
  date: string;
