export interface Transaction {
  id: string;
  businessId: string;
  businessName: string;
  type: 'credit_purchase' | 'promotion_spend';
  amount: number; // Credits
  amountNGN?: number; // Real currency cost (only for purchases)
  description: string;
  date: string;
  status: 'success' | 'failed' | 'pending';
}

export interface Event {
  id: string;
  title: string;
  description: string;
  date: string; // ISO string YYYY-MM-DD
  time: string;
  location: string;
  image: string;
  organizer: string;
  organizerId?: string;
  category: string;
  price: string;
  attendees: number;
  tags: string[];
}

export interface EventComment {
  id: string;
  eventId: string;
  userName: string;
  userImage: string;
  content: string;
  timestamp: string;
  status?: 'active' | 'flagged' | 'hidden';
}

// Table: PageView / EventLog
export interface AnalyticsEvent {
  id: string;
  businessId: string;
  type: 'view' | 'website_click' | 'call_click' | 'email_click' | 'whatsapp_click' | 'share';
  timestamp: number;
  userId?: string;
}

// Table: DailyAnalytics
export interface DailyMetric {
  date: string; // Primary Key Part 1 (YYYY-MM-DD)
  businessId: string; // Primary Key Part 2
  views: number;
  clicks: number;
  shares: number;
  uniqueVisitors: number; // Count of distinct userIds
}

export interface Notification {
  id: string;
  userId: string;
  type: 'review' | 'system' | 'promotion';
  title: string;
  message: string;
  date: string;
  isRead: boolean;
  link?: string;
}

export interface MarketingCampaign {
  id: string;
  name: string;
  status: 'active' | 'paused' | 'completed' | 'draft';
  channel: 'Google Ads' | 'Facebook' | 'Email' | 'Instagram';
  budget: number;
  spent: number;
  roi: string;
  startDate: string;
  endDate: string;
}

export type AdStatus = 'active' | 'paused' | 'expired';
export type AdLocation = 'Homepage Banner' | 'Listing Sidebar' | 'Search Results Top';

export interface AdPlacement {
  id: string;
  name: string;
  status: AdStatus;
  location: AdLocation;
  imageUrl: string;
  destinationUrl: string;
  impressions: number;
  clicks: number;
  startDate: string;
  endDate: string;
  targeting: {
    category?: string; // e.g., 'Food', 'Hotels'
  };
}

// --- CMS Configuration Types ---

export interface NavLink {
  id: string;
  label: string;
  path: string;
}

export interface HeaderConfig {
  isVisible: boolean;
  logoText: string;
  showAuthButtons: boolean;
  navLinks: NavLink[];
}

export interface HeroConfig {
  isVisible: boolean;
  title: string;
  highlightText: string;
  subtitle: string;
  backgroundImage: string;
  showSearchBar: boolean;
  tags: string[];
}

export interface FooterConfig {
  isVisible: boolean;
  aboutText: string;
  showSocialLinks: boolean;
  copyrightText: string;
}

export interface SiteConfig {
  header: HeaderConfig;
  hero: HeroConfig;
  footer: FooterConfig;
}

// --- Email Settings ---
export interface SmtpConfig {
  host: string;
  port: number;
  user: string;
  pass: string;
  encryption: 'none' | 'ssl';
}

export interface MailgunConfig {
  apiKey: string;
  domain: string;
}

export interface SendGridConfig {
  apiKey: string;
}

export type EmailConfig = {
  provider: 'smtp';
  settings: SmtpConfig;
} | {
  provider: 'mailgun';
  settings: MailgunConfig;
} | {
  provider: 'sendgrid';
  settings: SendGridConfig;
};

// --- Community Types ---

export interface CommunityComment {
  id: string;
  author: {
      name: string;
      image: string;
  };
  content: string;
  timestamp: string;
  upvotes: number;
  replies: CommunityComment[];
}

export interface CommunityThread {
  id: string;
  title: string;
  content: string; // HTML content
  author: {
      name: string;
      image: string;
      role: string;
  };
  category: string;
  upvotes: number;
  downvotes: number;
  commentCount: number;
  timestamp: string;
  userVote?: 'up' | 'down' | null;
  comments: CommunityComment[];
}

import React, { useState, useEffect } from 'react';
import { Link, Outlet, useLocation, useNavigate } from 'react-router-dom';
import { useAuth } from '../../context/AuthContext';
import { useTheme } from '../../context/ThemeContext';
import { 
  LayoutDashboard, BarChart3, Megaphone, ShoppingCart, List, Settings, 
  FileText, Menu, X, Sun, Moon, LogOut, ChevronDown, Bell, Search, Globe, 
  Wallet, MessageSquare, Users, TrendingUp, Activity, File, BookOpen, Mail, HelpCircle, MessageSquareQuote, Layout, Target
} from 'lucide-react';
import { Button } from './AdminComponents';
import { Permission } from '../../types';

const AdminLayout: React.FC = () => {
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);
  const [openMenus, setOpenMenus] = useState<Record<string, boolean>>({});
  const { user, logout, checkPermission } = useAuth();
  const { theme, toggleTheme } = useTheme();
  const location = useLocation();
  const navigate = useNavigate();

  // Redirect if not authorized
  React.useEffect(() => {
    if (user && !checkPermission('view_admin_dashboard')) {
      navigate('/');
    }
  }, [user, navigate, checkPermission]);

  const toggleSidebar = () => setIsSidebarOpen(!isSidebarOpen);

  const toggleMenu = (name: string) => {
    setOpenMenus(prev => ({ ...prev, [name]: !prev[name] }));
  };

  interface NavItem {
    name: string;
    path: string;
    icon: React.ElementType;
    permission?: Permission;
    children?: NavItem[];
  }

  const navItems: NavItem[] = [
    { name: 'Dashboard', path: '/admin', icon: LayoutDashboard },
    { name: 'Wallet', path: '/admin/orders', icon: Wallet, permission: 'manage_orders' },
    { 
      name: 'Analytics', 
      path: '/admin/analytics', 
      icon: BarChart3,
      children: [
        { name: 'Overview', path: '/admin/analytics', icon: LayoutDashboard },
        { name: 'Traffic Reports', path: '/admin/analytics/traffic', icon: TrendingUp },
        { name: 'User Insights', path: '/admin/analytics/insights', icon: Users },
        { name: 'Real-time', path: '/admin/analytics/realtime', icon: Activity },
        { name: 'Custom Reports', path: '/admin/analytics/custom', icon: FileText },
      ]
    },
    { 
      name: 'Content', 
      path: '/admin/content', 
      icon: FileText, 
      permission: 'manage_content',
      children: [
        { name: 'Site Config', path: '/admin/content/config', icon: Layout },
        { name: 'CMS Pages', path: '/admin/content/pages', icon: File },
        { name: 'Blog', path: '/admin/content/blog', icon: BookOpen },
        { name: 'Newsletters', path: '/admin/content/newsletters', icon: Mail },
        { name: 'FAQ', path: '/admin/content/faq', icon: HelpCircle },
        { name: 'Testimonials', path: '/admin/content/testimonials', icon: MessageSquareQuote },
      ]
    }, 
    { name: 'Listings', path: '/admin/listings', icon: List, permission: 'manage_listings' },
    { name: 'Marketing', path: '/admin/marketing', icon: Megaphone, permission: 'manage_marketing' },
    { name: 'Ads Manager', path: '/admin/ads', icon: Target, permission: 'manage_marketing' },
    { name: 'Settings', path: '/admin/settings', icon: Settings, permission: 'manage_settings' },
  ];

  // Auto-expand menu if child is active
  useEffect(() => {
    const activeParent = navItems.find(item => item.children?.some(child => location.pathname === child.path));
    if (activeParent && !openMenus[activeParent.name]) {
        setOpenMenus(prev => ({ ...prev, [activeParent.name]: true }));
    }
  }, [location.pathname]);

  if (!user) return null;

  return (
    <div className="min-h-screen bg-[#F3F4F8] dark:bg-[#0B0E14] flex font-sans text-slate-900 dark:text-slate-50 transition-colors duration-300">

      {/* Sidebar */}
      <aside 
        className={`fixed inset-y-0 left-0 z-50 w-64 bg-white dark:bg-[#151923] border-r border-transparent dark:border-slate-800 transform transition-transform duration-300 ease-in-out ${
          isSidebarOpen ? 'translate-x-0' : '-translate-x-full'
        } lg:relative lg:translate-x-0 flex flex-col justify-between`}
      >
        <div className="overflow-y-auto custom-scrollbar flex-1">
            {/* Logo */}
            <div className="h-24 flex items-center px-8 sticky top-0 bg-white dark:bg-[#151923] z-10">
                <Link to="/" className="flex items-center gap-3">
                <div className="w-10 h-10 rounded-xl bg-indigo-600 flex items-center justify-center text-white font-bold shadow-lg shadow-indigo-600/30">
                    V
                </div>
                <span className="text-xl font-extrabold text-slate-900 dark:text-white tracking-tight">Hub Admin</span>
                </Link>
            </div>

            {/* Navigation */}
            <nav className="px-4 space-y-2 mb-6">
                {navItems.map((item) => {
                    if (item.permission && !checkPermission(item.permission)) return null;

                    const hasChildren = item.children && item.children.length > 0;
                    const isChildActive = item.children?.some(child => location.pathname === child.path);
                    const isActive = location.pathname === item.path || isChildActive;
                    const isOpen = openMenus[item.name];

                    return (
                    <div key={item.name}>
                        <div
                            onClick={() => hasChildren ? toggleMenu(item.name) : navigate(item.path)}
                            className={`flex items-center justify-between px-4 py-3.5 rounded-2xl text-sm font-semibold transition-all duration-200 cursor-pointer ${
                            isActive && !hasChildren
                                ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-600/20' 
                                : 'text-gray-500 dark:text-gray-400 hover:bg-gray-50 dark:hover:bg-gray-800 hover:text-indigo-600 dark:hover:text-white'
                            }`}
                        >
                            <div className="flex items-center gap-4">
                                <item.icon size={20} className={isActive && !hasChildren ? 'text-white' : 'text-current'} />
                                {item.name}
                            </div>
                            {hasChildren && (
                                <ChevronDown size={16} className={`transition-transform duration-200 ${isOpen ? 'rotate-180' : ''}`} />
                            )}
                        </div>

                        {/* Dropdown Items */}
                        {hasChildren && isOpen && (
                            <div className="mt-1 ml-4 space-y-1 border-l-2 border-indigo-100 dark:border-gray-800 pl-3">
                                {item.children?.map(child => {
                                    const isChildLinkActive = location.pathname === child.path;
                                    return (
                                        <Link
                                            key={child.path}
                                            to={child.path}
                                            className={`flex items-center gap-3 px-4 py-2.5 rounded-xl text-sm font-medium transition-colors ${
                                                isChildLinkActive 
                                                ? 'bg-indigo-50 dark:bg-indigo-900/20 text-indigo-600 dark:text-indigo-300' 
                                                : 'text-gray-500 dark:text-gray-400 hover:text-gray-900 dark:hover:text-gray-200 hover:bg-gray-50 dark:hover:bg-gray-800/50'
                                            }`}
                                        >
                                            {/* Optional: Add icon for sub-items too if needed, here keeping it simple */}
                                            {child.name}
                                        </Link>
                                    );
                                })}
                            </div>
                        )}
                    </div>
                    );
                })}
            </nav>
        </div>

        {/* Bottom Actions */}
        <div className="p-6 space-y-4 bg-white dark:bg-[#151923]">
            {/* Theme Toggle Switch */}
            <div className="flex items-center justify-between bg-gray-100 dark:bg-gray-800 rounded-full p-1.5 cursor-pointer" onClick={toggleTheme}>
                <div className={`p-2 rounded-full transition-all duration-300 ${theme === 'light' ? 'bg-white shadow-sm text-yellow-500' : 'text-gray-400'}`}>
                    <Sun size={16} />
                </div>
                <div className={`p-2 rounded-full transition-all duration-300 ${theme === 'dark' ? 'bg-slate-700 shadow-sm text-indigo-400' : 'text-gray-400'}`}>
                    <Moon size={16} />
                </div>
            </div>

            <button 
                onClick={logout}
                className="flex items-center gap-3 px-4 py-3 text-gray-500 dark:text-gray-400 hover:text-red-500 dark:hover:text-red-400 text-sm font-semibold transition-colors w-full"
            >
                <LogOut size={20} />
                Sign out
            </button>
        </div>
      </aside>

      {/* Main Content Wrapper */}
      <div className="flex-1 flex flex-col min-w-0 overflow-hidden h-screen">

        {/* Header */}
        <header className="h-24 bg-[#F3F4F8] dark:bg-[#0B0E14] flex items-center justify-between px-8 pt-4">
            <div className="flex flex-col">
                <h1 className="text-2xl font-bold text-slate-900 dark:text-white">Hello, {user.name.split(' ')[0]}</h1>
                <p className="text-gray-500 dark:text-gray-400 text-sm">Welcome back to your dashboard</p>
            </div>

            <div className="flex items-center gap-6">
                <div className="hidden md:flex relative">
                    <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
                    <input 
                        type="text" 
                        placeholder="Search..." 
                        className="pl-12 pr-4 py-3 rounded-2xl border-none bg-white dark:bg-[#151923] text-sm w-64 focus:outline-none focus:ring-2 focus:ring-indigo-500 shadow-sm"
                    />
                </div>

                <button className="relative p-3 bg-white dark:bg-[#151923] rounded-xl shadow-sm hover:bg-gray-50 dark:hover:bg-gray-800 transition-colors">
                    <Bell size={20} className="text-gray-600 dark:text-gray-300" />
                    <span className="absolute top-2.5 right-3 w-2 h-2 bg-red-500 rounded-full border-2 border-white dark:border-[#151923]"></span>
                </button>

                <div className="flex items-center gap-3">
                    <img src={user.image} alt="" className="w-12 h-12 rounded-xl object-cover shadow-sm cursor-pointer" onClick={() => navigate('/profile')} />
                    <div className="hidden sm:block">
                        <p className="text-sm font-bold text-slate-900 dark:text-white leading-none mb-1">{user.name}</p>
                        <p className="text-xs text-gray-500 capitalize">{user.role}</p>
                    </div>
                </div>
            </div>
        </header>

        {/* Content Scroll Area */}
        <main className="flex-1 px-8 pb-8 overflow-y-auto custom-scrollbar">
          <Outlet />
        </main>
      </div>
    </div>
  );
};

export default AdminLayout;

import React, { useState } from 'react';
import { Card, CardContent, CardHeader, CardTitle, Table, TableBody, TableCell, TableHead, TableHeader, TableRow, Badge, Button, Input, Modal } from '../../components/admin/AdminComponents';
import { Zap, Star, Plus, Trash2, Search, X } from 'lucide-react';
import { MOCK_BUSINESSES } from '../../constants';
import { Business } from '../../types';

const AdminAds: React.FC = () => {
    const [businesses, setBusinesses] = useState<Business[]>(MOCK_BUSINESSES);
    const [activeTab, setActiveTab] = useState<'sponsored' | 'featured'>('sponsored');
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [searchTerm, setSearchTerm] = useState('');

    const sponsoredListings = businesses.filter(b => b.isPromoted);
    const featuredListings = businesses.filter(b => b.isFeatured);

    const handleAdd = (business: Business) => {
        setBusinesses(businesses.map(b => {
            if (b.id === business.id) {
                return activeTab === 'sponsored' 
                    ? { ...b, isPromoted: true } 
                    : { ...b, isFeatured: true };
            }
            return b;
        }));
        setIsModalOpen(false);
        setSearchTerm('');
    };

    const handleRemove = (businessId: string, type: 'sponsored' | 'featured') => {
        if(window.confirm(`Are you sure you want to remove this from ${type === 'sponsored' ? 'Sponsored Listings' : "Editor's Picks"}?`)) {
            setBusinesses(businesses.map(b => {
                if (b.id === businessId) {
                    return type === 'sponsored' 
                        ? { ...b, isPromoted: false }
                        : { ...b, isFeatured: false };
                }
                return b;
            }));
        }
    };

    const filteredOptions = businesses
        .filter(b => activeTab === 'sponsored' ? !b.isPromoted : !b.isFeatured)
        .filter(b => b.name.toLowerCase().includes(searchTerm.toLowerCase()));

    return (
        <div className="animate-fade-in space-y-6">
            <div className="flex flex-col sm:flex-row justify-between sm:items-center mb-6 gap-4">
                <div>
                    <h1 className="text-3xl font-bold text-slate-900 dark:text-slate-50">Ads Manager</h1>
                    <p className="text-gray-500 dark:text-gray-400">Manage internal placements for Sponsored Listings and Editor's Picks.</p>
                </div>
            </div>

            <div className="flex gap-1 sm:gap-2 mb-6 border-b border-slate-200 dark:border-slate-800 overflow-x-auto">
                <button 
                    onClick={() => setActiveTab('sponsored')}
                    className={`px-4 py-2 text-sm font-bold rounded-t-lg transition-colors whitespace-nowrap flex items-center gap-2 ${activeTab === 'sponsored' ? 'text-primary border-b-2 border-primary bg-primary/5' : 'text-slate-500 hover:bg-slate-50 dark:hover:bg-slate-800'}`}
                >
                    <Zap size={16} /> Sponsored Listings
                </button>
                 <button 
                    onClick={() => setActiveTab('featured')}
                    className={`px-4 py-2 text-sm font-bold rounded-t-lg transition-colors whitespace-nowrap flex items-center gap-2 ${activeTab === 'featured' ? 'text-primary border-b-2 border-primary bg-primary/5' : 'text-slate-500 hover:bg-slate-50 dark:hover:bg-slate-800'}`}
                >
                    <Star size={16} /> Editor's Picks
                </button>
            </div>

            <Card>
                <CardHeader className="flex flex-row items-center justify-between">
                    <CardTitle>{activeTab === 'sponsored' ? 'Sponsored Businesses' : "Featured Listings"}</CardTitle>
                    <Button size="sm" onClick={() => setIsModalOpen(true)}>
                        <Plus size={16} className="mr-2" /> 
                        {activeTab === 'sponsored' ? 'Add Sponsored' : 'Add Featured'}
                    </Button>
                </CardHeader>
                <CardContent>
                    <Table>
                        <TableHeader>
                            <TableRow>
                                <TableHead>Business Name</TableHead>
                                <TableHead>Category</TableHead>
                                <TableHead>Location</TableHead>
                                <TableHead>Rating</TableHead>
                                <TableHead>Status</TableHead>
                                <TableHead>Actions</TableHead>
                            </TableRow>
                        </TableHeader>
                        <TableBody>
                            {(activeTab === 'sponsored' ? sponsoredListings : featuredListings).map(business => (
                                <TableRow key={business.id}>
                                    <TableCell className="font-medium flex items-center gap-3">
                                        <img src={business.image} alt={business.name} className="w-10 h-10 rounded-lg object-cover bg-slate-100 dark:bg-slate-800" />
                                        {business.name}
                                    </TableCell>
                                    <TableCell>{business.category}</TableCell>
                                    <TableCell>{business.location}</TableCell>
                                    <TableCell className="flex items-center gap-1">
                                        <Star size={12} className="fill-yellow-400 text-yellow-400" /> {business.rating}
                                    </TableCell>
                                    <TableCell>
                                        <Badge variant={business.isOpen ? 'success' : 'secondary'}>{business.isOpen ? 'Open' : 'Closed'}</Badge>
                                    </TableCell>
                                    <TableCell>
                                        <Button 
                                            variant="ghost" 
                                            size="icon" 
                                            onClick={() => handleRemove(business.id, activeTab)} 
                                            className="text-red-500 hover:text-red-600 hover:bg-red-50 dark:hover:bg-red-900/20"
                                            title="Remove placement"
                                        >
                                            <Trash2 size={16} />
                                        </Button>
                                    </TableCell>
                                </TableRow>
                            ))}
                            {(activeTab === 'sponsored' ? sponsoredListings : featuredListings).length === 0 && (
                                <TableRow>
                                    <TableCell colSpan={6} className="text-center py-8 text-gray-500">
                                        No {activeTab === 'sponsored' ? 'sponsored' : 'featured'} listings yet.
                                    </TableCell>
                                </TableRow>
                            )}
                        </TableBody>
                    </Table>
                </CardContent>
            </Card>

            <Modal 
                isOpen={isModalOpen} 
                onClose={() => setIsModalOpen(false)} 
                title={`Add to ${activeTab === 'sponsored' ? 'Sponsored' : "Editor's Picks"}`}
            >
                <div className="space-y-4">
                    <div className="relative">
                        <Search className="absolute left-3 top-2.5 text-gray-400" size={18} />
                        <Input 
                            placeholder="Search businesses..." 
                            className="pl-10"
                            value={searchTerm}
                            onChange={(e) => setSearchTerm(e.target.value)}
                            autoFocus
                        />
                    </div>

                    <div className="max-h-60 overflow-y-auto space-y-2 border border-slate-200 dark:border-slate-800 rounded-lg p-2">
                        {filteredOptions.length > 0 ? (
                            filteredOptions.map(b => (
                                <div 
                                    key={b.id} 
                                    className="flex items-center justify-between p-3 hover:bg-slate-50 dark:hover:bg-slate-800 rounded-lg cursor-pointer transition-colors group"
                                    onClick={() => handleAdd(b)}
                                >
                                    <div className="flex items-center gap-3">
                                        <img src={b.image} alt="" className="w-10 h-10 rounded object-cover bg-slate-200" />
                                        <div>
                                            <div className="text-sm font-bold text-slate-900 dark:text-slate-50">{b.name}</div>
                                            <div className="text-xs text-gray-500">{b.location}</div>
                                        </div>
                                    </div>
                                    <Plus size={18} className="text-gray-400 group-hover:text-primary" />
                                </div>
                            ))
                        ) : (
                            <div className="text-center py-4 text-sm text-gray-500">
                                {searchTerm ? 'No matching businesses found.' : 'Type to search...'}
                            </div>
                        )}
                    </div>
                </div>
            </Modal>
        </div>
    );
};

export default AdminAds;

import React, { useEffect } from 'react';
