import React, { useState, useRef, useEffect } from 'react';
import { Card, CardContent, CardHeader, CardTitle, Table, TableBody, TableCell, TableHead, TableHeader, TableRow, Badge, Button, Input, Modal, Select } from '../../components/admin/AdminComponents';
import { Megaphone, Plus, Edit, Trash2, Play, Pause, UploadCloud, Search, Star, Zap, Image as ImageIcon } from 'lucide-react';
import { MOCK_ADS, MOCK_BUSINESSES, CATEGORIES } from '../../constants';
import { AdPlacement, AdStatus, Business } from '../../types';

// --- Ads Manager (Banner Ads) ---
const BannerAdsManager: React.FC = () => {
    const [ads, setAds] = useState<AdPlacement[]>(MOCK_ADS);
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [editingAd, setEditingAd] = useState<AdPlacement | null>(null);

    // Modal Form State
    const [formData, setFormData] = useState<Omit<AdPlacement, 'id' | 'impressions' | 'clicks'>>({
        name: '', status: 'active', location: 'Homepage Banner', imageUrl: '', destinationUrl: '',
        startDate: new Date().toISOString().split('T')[0], endDate: '', targeting: {}
    });
    const [imagePreview, setImagePreview] = useState<string | null>(null);
    const fileInputRef = useRef<HTMLInputElement>(null);

    const handleOpenModal = (ad: AdPlacement | null = null) => {
        setEditingAd(ad);
        if (ad) {
            setFormData({
                name: ad.name,
                status: ad.status,
                location: ad.location,
                imageUrl: ad.imageUrl,
                destinationUrl: ad.destinationUrl,
                startDate: ad.startDate.split('T')[0],
                endDate: ad.endDate.split('T')[0],
                targeting: ad.targeting
            });
            setImagePreview(ad.imageUrl);
        } else {
            setFormData({
                name: '', status: 'active', location: 'Homepage Banner', imageUrl: '', destinationUrl: '',
                startDate: new Date().toISOString().split('T')[0], endDate: '', targeting: {}
            });
            setImagePreview(null);
        }
        setIsModalOpen(true);
    };

    const handleFileSelect = (file: File | null) => {
        if (file && file.type.startsWith('image/')) {
            const previewUrl = URL.createObjectURL(file);
            setImagePreview(previewUrl);
            setFormData(prev => ({ ...prev, imageUrl: previewUrl }));
        } else {
            setImagePreview(null);
            setFormData(prev => ({ ...prev, imageUrl: '' }));
        }
    };

    const handleSaveAd = (e: React.FormEvent) => {
        e.preventDefault();
        const adData = { 
            ...formData, 
            id: editingAd ? editingAd.id : `ad_${Date.now()}`,
            impressions: editingAd ? editingAd.impressions : 0,
            clicks: editingAd ? editingAd.clicks : 0
        };

        if (editingAd) {
            setAds(ads.map(ad => ad.id === adData.id ? adData : ad));
        } else {
            setAds([...ads, adData]);
        }
        setIsModalOpen(false);
    };

    const handleDeleteAd = (adId: string) => {
        if (window.confirm("Are you sure you want to delete this ad?")) {
            setAds(ads.filter(ad => ad.id !== adId));
        }
    };

    const handleToggleStatus = (adId: string) => {
        setAds(ads.map(ad => {
            if (ad.id === adId) {
                return { ...ad, status: ad.status === 'active' ? 'paused' : 'active' };
            }
            return ad;
        }));
    };

    const getStatusBadge = (status: AdStatus) => {
        switch (status) {
            case 'active': return <Badge variant="success">Active</Badge>;
            case 'paused': return <Badge variant="warning">Paused</Badge>;
            case 'expired': return <Badge variant="secondary">Expired</Badge>;
        }
    };

    return (
        <>
            <Card>
                <CardHeader className="flex flex-row items-center justify-between">
                    <CardTitle className="flex items-center gap-2"><ImageIcon size={18} /> Banner Placements</CardTitle>
                    <Button size="sm" onClick={() => handleOpenModal()}>
                        <Plus size={16} className="mr-2" /> New Banner
                    </Button>
                </CardHeader>
                <CardContent>
                    <Table>
                        <TableHeader>
                            <TableRow>
                                <TableHead>Creative</TableHead>
                                <TableHead>Status</TableHead>
                                <TableHead>Placement</TableHead>
                                <TableHead>Impressions</TableHead>
                                <TableHead>Clicks</TableHead>
                                <TableHead>Actions</TableHead>
                            </TableRow>
                        </TableHeader>
                        <TableBody>
                            {ads.map(ad => (
                                <TableRow key={ad.id}>
                                    <TableCell className="font-medium flex items-center gap-3">
                                        <img src={ad.imageUrl} alt={ad.name} className="w-20 h-10 object-cover rounded-md bg-slate-100 dark:bg-slate-800" />
                                        {ad.name}
                                    </TableCell>
                                    <TableCell>{getStatusBadge(ad.status)}</TableCell>
                                    <TableCell>{ad.location}</TableCell>
                                    <TableCell>{ad.impressions.toLocaleString()}</TableCell>
                                    <TableCell>{ad.clicks.toLocaleString()}</TableCell>
                                    <TableCell className="flex gap-1">
                                        <Button variant="ghost" size="icon" onClick={() => handleToggleStatus(ad.id)}>
                                            {ad.status === 'active' ? <Pause size={14} /> : <Play size={14} />}
                                        </Button>
                                        <Button variant="ghost" size="icon" onClick={() => handleOpenModal(ad)}>
                                            <Edit size={14} />
                                        </Button>
                                        <Button variant="ghost" size="icon" onClick={() => handleDeleteAd(ad.id)} className="text-red-500">
                                            <Trash2 size={14} />
                                        </Button>
                                    </TableCell>
                                </TableRow>
                            ))}
                        </TableBody>
                    </Table>
                </CardContent>
            </Card>

            <Modal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} title={editingAd ? "Edit Banner" : "New Banner"}>
                <form onSubmit={handleSaveAd} className="space-y-4">
                    <div>
                        <label className="text-sm font-medium">Ad Name</label>
                        <Input value={formData.name} onChange={(e) => setFormData({...formData, name: e.target.value})} required />
                    </div>
                    <div>
                        <label className="text-sm font-medium">Banner Image</label>
                        <div 
                            onClick={() => fileInputRef.current?.click()}
                            className="mt-1 border-2 border-dashed rounded-lg p-4 text-center cursor-pointer border-slate-300 dark:border-slate-600 hover:border-primary"
                        >
                            {imagePreview ? (
                                <img src={imagePreview} className="h-24 mx-auto object-contain" alt="Preview" />
                            ) : (
                                <div className="text-slate-400"><UploadCloud className="mx-auto mb-1"/> Upload Image</div>
                            )}
                            <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={(e) => handleFileSelect(e.target.files ? e.target.files[0] : null)} />
                        </div>
                    </div>
                    <div className="grid grid-cols-2 gap-4">
                        <div>
                            <label className="text-sm font-medium">Placement</label>
                            <Select value={formData.location} onChange={(e) => setFormData({...formData, location: e.target.value as any})}>
                                <option>Homepage Banner</option>
                                <option>Listing Sidebar</option>
                                <option>Search Results Top</option>
                            </Select>
                        </div>
                        <div>
                            <label className="text-sm font-medium">Category Target</label>
                            <Select value={formData.targeting.category || ''} onChange={(e) => setFormData({...formData, targeting: { category: e.target.value }})}>
                                <option value="">All Categories</option>
                                {CATEGORIES.map(c => <option key={c.id} value={c.name}>{c.name}</option>)}
                            </Select>
                        </div>
                    </div>
                    <div className="flex justify-end gap-2 pt-4">
                        <Button type="button" variant="outline" onClick={() => setIsModalOpen(false)}>Cancel</Button>
