const ListingSelector: React.FC<{ isOpen: boolean, onClose: () => void, onSelect: (business: Business) => void, title: string, excludeIds: string[] }> = ({ isOpen, onClose, onSelect, title, excludeIds }) => {
    const [search, setSearch] = useState('');
    const filtered = MOCK_BUSINESSES.filter(b => 
        !excludeIds.includes(b.id) && 
        b.name.toLowerCase().includes(search.toLowerCase())
    );

    return (
        <Modal isOpen={isOpen} onClose={onClose} title={title}>
            <div className="space-y-4">
                <div className="relative">
                    <Search className="absolute left-3 top-2.5 text-gray-400" size={16} />
                    <Input 
                        placeholder="Search businesses..." 
                        className="pl-9"
                        value={search}
                        onChange={(e) => setSearch(e.target.value)}
                        autoFocus
                    />
                </div>
                <div className="max-h-60 overflow-y-auto border rounded-lg divide-y dark:border-gray-700">
                    {filtered.map(b => (
                        <div key={b.id} className="p-3 hover:bg-slate-50 dark:hover:bg-slate-800 cursor-pointer flex justify-between items-center" onClick={() => onSelect(b)}>
                            <div>
                                <div className="font-bold text-sm">{b.name}</div>
                                <div className="text-xs text-gray-500">{b.category} • {b.location}</div>
                            </div>
                            <Button size="sm" variant="ghost">Select</Button>
                        </div>
                    ))}
                    {filtered.length === 0 && <div className="p-4 text-center text-gray-500 text-sm">No businesses found.</div>}
                </div>
            </div>
        </Modal>
    );
};

