                {business.instagramHandle && (
                   <a 
                      href={`https://instagram.com/${business.instagramHandle}`} 
                      onClick={() => handleContactClick('instagram_click')}
                      target="_blank" 
                      rel="noopener noreferrer" 
                      className="block w-full text-center bg-gradient-to-tr from-purple-600 via-pink-600 to-yellow-500 hover:opacity-90 text-white font-bold py-3 rounded-xl shadow-lg shadow-pink-500/30 transition-all mb-3 flex items-center justify-center gap-2"
