import React, { useState } from 'react';
import { Star, ThumbsUp, ThumbsDown, Camera, MessageCircle, CornerDownRight, Flag, Award, Send, X } from 'lucide-react';
import * as Icons from 'lucide-react';
import { Review, User } from '../types';
