// --- Rating Breakdown Component ---
export const RatingBreakdown: React.FC<{ reviews: Review[] }> = ({ reviews }) => {
    const total = reviews.length;
    const counts = { 5: 0, 4: 0, 3: 0, 2: 0, 1: 0 };

    reviews.forEach(r => {
        const rating = Math.round(r.rating) as 1|2|3|4|5;
        if (counts[rating] !== undefined) counts[rating]++;
    });

    return (
        <div className="glass-card p-6 rounded-2xl mb-8">
            <h4 className="font-bold text-dark dark:text-white mb-4 text-lg">Rating Breakdown</h4>
            <div className="space-y-3">
                {[5, 4, 3, 2, 1].map(star => {
                    const count = counts[star as keyof typeof counts];
                    const percentage = total > 0 ? (count / total) * 100 : 0;
                    return (
                        <div key={star} className="flex items-center gap-3">
                            <div className="flex items-center w-12 gap-1 text-sm font-medium text-gray-600 dark:text-gray-300">
                                {star} <Star size={12} className="fill-gray-400 text-gray-400" />
                            </div>
                            <div className="flex-1 h-2.5 bg-gray-100 dark:bg-gray-700 rounded-full overflow-hidden">
                                <div 
                                    className="h-full bg-yellow-400 rounded-full transition-all duration-500"
                                    style={{ width: `${percentage}%` }}
                                ></div>
                            </div>
                            <div className="w-10 text-xs text-gray-400 text-right">{Math.round(percentage)}%</div>
                        </div>
                    );
                })}
            </div>
        </div>
    );
};

// --- Review Form Component ---
interface ReviewFormProps {
    onSubmit: (rating: number, text: string, photos: File[]) => void;
    user: User;
}

export const ReviewForm: React.FC<ReviewFormProps> = ({ onSubmit, user }) => {
    const [rating, setRating] = useState(0);
    const [text, setText] = useState('');
    const [hoveredRating, setHoveredRating] = useState(0);

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        if (rating === 0) return alert('Please select a rating');
        onSubmit(rating, text, []);
        setRating(0);
        setText('');
    };

    return (
        <div className="glass-card p-6 rounded-2xl mb-8 border border-primary/10 bg-primary/5 dark:bg-primary/10">
            <h4 className="font-bold text-dark dark:text-white mb-4">Write a Review</h4>
            <form onSubmit={handleSubmit}>
                <div className="mb-4">
                    <label className="block text-xs font-bold text-gray-500 dark:text-gray-400 uppercase tracking-wider mb-2">Rating</label>
                    <div className="flex gap-2">
                        {[1, 2, 3, 4, 5].map((star) => (
                            <button
                                type="button"
                                key={star}
                                onMouseEnter={() => setHoveredRating(star)}
                                onMouseLeave={() => setHoveredRating(0)}
                                onClick={() => setRating(star)}
                                className="focus:outline-none transition-transform hover:scale-110"
                            >
                                <Star 
                                    size={28} 
                                    className={`${star <= (hoveredRating || rating) ? 'fill-yellow-400 text-yellow-400' : 'text-gray-300 dark:text-gray-600'}`} 
                                />
                            </button>
                        ))}
                    </div>
                </div>

                <div className="mb-4">
                    <label className="block text-xs font-bold text-gray-500 dark:text-gray-400 uppercase tracking-wider mb-2">Review</label>
                    <textarea
                        value={text}
                        onChange={(e) => setText(e.target.value)}
                        rows={4}
                        placeholder="Share your experience with others..."
                        className="w-full bg-white dark:bg-slate-900 rounded-xl p-4 text-sm border border-gray-200 dark:border-gray-700 focus:outline-none focus:border-primary transition-colors text-dark dark:text-white placeholder-gray-400"
                        required
                    />
                </div>

                <div className="flex justify-between items-center">
                    <button type="button" className="flex items-center gap-2 text-gray-500 dark:text-gray-400 hover:text-dark dark:hover:text-white text-sm font-medium px-3 py-2 rounded-lg hover:bg-white dark:hover:bg-gray-800 transition-colors">
                        <Camera size={18} /> Add Photos
                    </button>

                    <button 
                        type="submit" 
                        disabled={!text || rating === 0}
                        className="bg-primary text-white font-bold px-6 py-2.5 rounded-xl shadow-lg shadow-red-500/30 hover:bg-red-600 disabled:opacity-50 disabled:cursor-not-allowed transition-all"
                    >
                        Post Review
                    </button>
                </div>
            </form>
        </div>
    );
};

// --- Review Card Component ---
interface ReviewCardProps {
    review: Review;
    currentUser: User | null;
    isOwner: boolean;
    onReply?: (reviewId: string, text: string) => void;
    onReport?: (reviewId: string) => void;
}

export const ReviewCard: React.FC<ReviewCardProps> = ({ review, currentUser, isOwner, onReply, onReport }) => {
    const navigate = useNavigate();
    const [vote, setVote] = useState<'yes' | 'no' | null>(null);
    const [likeCount, setLikeCount] = useState(review.helpfulCount);
    const [isReported, setIsReported] = useState(false);

    // Reply State
    const [isReplying, setIsReplying] = useState(false);
    const [replyText, setReplyText] = useState('');

    const reviewUser = MOCK_USERS_LIST.find(u => u.id === review.userId) || { badges: [], reputationPoints: 0 };
    const isReviewAuthor = currentUser?.id === review.userId;

    const handleVote = (type: 'yes' | 'no') => {
        if (!currentUser) {
            if (window.confirm("Please log in to vote on reviews. Go to login?")) {
                navigate('/login');
            }
            return;
        }

        if (isReviewAuthor) return;

        if (vote === type) {
            setVote(null);
            if (type === 'yes') setLikeCount(prev => prev - 1);
        } else {
            if (vote === 'yes') setLikeCount(prev => prev - 1);
            setVote(type);
            if (type === 'yes') setLikeCount(prev => prev + 1);
        }
    };

    const handleReport = () => {
        if (!currentUser) {
             if (window.confirm("Please log in to report content. Go to login?")) {
                navigate('/login');
            }
            return;
        }

        if (window.confirm("Report this review as inappropriate?")) {
            setIsReported(true);
            if (onReport) onReport(review.id);
            alert("Review flagged for moderation.");
        }
    };

    const submitReply = () => {
        if (!replyText.trim()) return;
        if (onReply) {
            onReply(review.id, replyText);
            setIsReplying(false);
            setReplyText('');
        } else {
            alert("Reply submitted! (Demo mode)");
            setIsReplying(false);
        }
    }

    if (review.status === 'hidden' && currentUser?.role !== 'admin') return null;

    return (
        <div className={`glass-card p-6 rounded-2xl mb-6 relative transition-all hover:shadow-lg ${review.status === 'flagged' && currentUser?.role === 'admin' ? 'border-2 border-red-200 bg-red-50 dark:bg-red-900/10' : ''}`}>
            {currentUser?.role === 'admin' && review.status !== 'active' && (
                 <div className="absolute top-2 right-2 px-2 py-0.5 bg-red-100 text-red-600 text-xs font-bold rounded uppercase">
                     {review.status}
                 </div>
            )}

            <div className="flex justify-between items-start mb-4">
                <div className="flex items-center gap-3">
                    <img 
                      src={review.userImage} 
                      alt={review.userName} 
                      className="w-10 h-10 rounded-full object-cover border border-gray-100 dark:border-gray-700" 
                    />
                    <div>
                        <div className="flex items-center gap-1.5 flex-wrap">
                            <h5 className="font-bold text-dark dark:text-white text-sm">{review.userName}</h5>
                            <div className="flex items-center gap-1">
                                {reviewUser.reputationPoints > 1500 && (
                                    <div className="flex items-center gap-0.5 bg-slate-950 dark:bg-white text-white dark:text-slate-950 px-1.5 py-0.5 rounded-[4px] text-[9px] font-black uppercase tracking-tighter" title="Top Contributor">
                                        <Award size={10} /> Pro
                                    </div>
                                )}
                                {reviewUser.badges && reviewUser.badges.length > 0 && (
                                    reviewUser.badges.map(bid => {
                                        const badge = MOCK_BADGES.find(b => b.id === bid);
                                        if (!badge) return null;
                                        const BadgeIcon = (Icons as any)[badge.icon] || Icons.Shield;
                                        return (
                                            <div key={bid} title={badge.name} className="w-4 h-4 rounded-md flex items-center justify-center bg-slate-100 dark:bg-slate-800 text-slate-500 border border-slate-200 dark:border-slate-700">
                                                <BadgeIcon size={10} />
                                            </div>
                                        );
                                    })
                                )}
                            </div>
                        </div>
                        <span className="text-xs text-gray-400">{new Date(review.date).toLocaleDateString()}</span>
                    </div>
                </div>
                <div className="flex bg-yellow-50 dark:bg-yellow-900/20 px-2 py-1 rounded text-yellow-600 dark:text-yellow-400 font-bold text-xs">
                    <Star size={12} className="fill-yellow-600 dark:fill-yellow-400 mr-1" /> {review.rating}.0
                </div>
            </div>

            <p className="text-graytext dark:text-gray-300 text-sm mb-4 leading-relaxed">{review.text}</p>

            {review.photos && review.photos.length > 0 && (
                <div className="flex gap-2 mb-4 overflow-x-auto pb-2">
                    {review.photos.map((photo, i) => (
                        <img key={i} src={photo} alt="Review attachment" className="h-20 w-20 object-cover rounded-lg border border-gray-100 dark:border-gray-700" />
                    ))}
                </div>
            )}

            <div className="flex items-center justify-between border-t border-gray-100 dark:border-gray-700 pt-4">
                <div className="flex items-center gap-4">
                    <div className="flex items-center gap-3">
                        <span className="text-xs text-gray-400 font-medium hidden sm:inline">Was this review helpful?</span>
                        <button 
                            onClick={() => handleVote('yes')}
                            disabled={isReviewAuthor}
                            className={`flex items-center gap-1 text-xs font-bold transition-colors ${vote === 'yes' ? 'text-green-600' : 'text-gray-400 hover:text-green-600'} ${isReviewAuthor ? 'cursor-not-allowed opacity-50' : ''}`}
                            title="Yes"
                        >
                            <ThumbsUp size={14} className={vote === 'yes' ? 'fill-green-600' : ''} /> {likeCount > 0 ? likeCount : ''}
                        </button>
                        <button 
                            onClick={() => handleVote('no')}
                            disabled={isReviewAuthor}
                            className={`flex items-center gap-1 text-xs font-bold transition-colors ${vote === 'no' ? 'text-red-500' : 'text-gray-400 hover:text-red-500'} ${isReviewAuthor ? 'cursor-not-allowed opacity-50' : ''}`}
                             title="No"
                        >
                            <ThumbsDown size={14} className={vote === 'no' ? 'fill-red-500' : ''} />
                        </button>
                    </div>

                    {isOwner && !review.reply && !isReplying && (
                        <button 
                            onClick={() => setIsReplying(true)}
                            className="flex items-center gap-1.5 text-xs font-bold text-primary hover:text-red-700 transition-colors bg-primary/5 px-2 py-1 rounded-md"
                        >
                            <MessageCircle size={14} /> Reply
                        </button>
                    )}
                </div>

                {!isReported ? (
                    <button onClick={handleReport} className="text-gray-300 hover:text-red-500 transition-colors" title="Report">
                        <Flag size={14} />
                    </button>
                ) : (
                    <span className="text-xs text-red-500 font-medium">Reported</span>
                )}
            </div>

            {/* Vendor Reply Input Area */}
            {isReplying && (
                <div className="mt-4 bg-gray-50 dark:bg-gray-800 rounded-2xl p-5 ml-2 sm:ml-6 border border-gray-200 dark:border-gray-700 animate-fade-in-up shadow-inner relative overflow-hidden">
                    <div className="absolute top-0 left-0 w-1 h-full bg-primary"></div>
                    <div className="flex justify-between items-center mb-3">
                        <label className="block text-xs font-bold text-gray-500 dark:text-gray-400 uppercase tracking-wider">Reply as Business Owner</label>
                        <button onClick={() => setIsReplying(false)} className="text-gray-400 hover:text-dark dark:hover:text-white transition-colors">
                            <X size={16} />
                        </button>
                    </div>
                    <textarea 
                        value={replyText}
                        onChange={(e) => setReplyText(e.target.value)}
                        placeholder="Thank the customer or address their concerns..."
                        rows={3}
                        className="w-full bg-white dark:bg-slate-900 border border-gray-200 dark:border-gray-600 rounded-xl p-4 text-sm focus:outline-none focus:border-primary mb-4 text-dark dark:text-white placeholder-gray-400 shadow-sm"
                        autoFocus
                    ></textarea>
                    <div className="flex justify-end gap-3">
                        <button 
                            onClick={() => setIsReplying(false)}
                            className="px-4 py-2 text-sm font-bold text-gray-500 hover:bg-white dark:hover:bg-gray-700 rounded-xl transition-all"
                        >
                            Cancel
                        </button>
                        <button 
                            onClick={submitReply}
                            disabled={!replyText.trim()}
                            className="bg-primary text-white px-6 py-2 rounded-xl text-sm font-bold shadow-lg shadow-red-500/20 hover:bg-red-600 transition-all flex items-center gap-2 disabled:opacity-50"
                        >
                           <Send size={14} /> Post Reply
                        </button>
                    </div>
                </div>
            )}

            {/* Vendor Reply Display */}
            {review.reply && (
                <div className="mt-4 bg-primary/5 dark:bg-white/5 rounded-2xl p-5 ml-2 sm:ml-6 border-l-4 border-primary relative">
                    <div className="flex items-center justify-between mb-2">
                        <div className="flex items-center gap-2">
                            <div className="bg-primary rounded-full p-1 text-white">
                                <CornerDownRight size={10} />
                            </div>
                            <span className="text-xs font-bold text-dark dark:text-white uppercase tracking-tight">Response from Owner</span>
                        </div>
                        <span className="text-[10px] text-gray-400 font-medium">{new Date(review.reply.date).toLocaleDateString()}</span>
                    </div>
                    <p className="text-sm text-gray-700 dark:text-gray-300 leading-relaxed italic">"{review.reply.text}"</p>
                </div>
            )}
        </div>
    );
};

import React, { useState, useEffect, useRef } from 'react';
import { useParams, Link } from 'react-router-dom';
import { MOCK_BUSINESSES, MOCK_REVIEWS } from '../constants';
import { Star, MapPin, Phone, Mail, Globe, Share2, Heart, Clock, CheckCircle, Instagram, MessageCircle, Facebook, Twitter, Link as LinkIcon, Check, Filter, ArrowUpDown, ShieldCheck, ToggleLeft, ToggleRight, ChevronLeft, ChevronRight, Package, ShoppingCart, Plus, Edit3, Trash2, X, UploadCloud, AlertCircle } from 'lucide-react';
import { useAuth } from '../context/AuthContext';
import BusinessCard from '../components/BusinessCard';
import { ReviewForm, RatingBreakdown, ReviewCard } from '../components/ReviewSystem';
import { Review, Product } from '../types';
import { analyticsService } from '../services/analytics';
import { notificationService } from '../services/notification';

const ProductCarousel: React.FC<{ 
    products: Product[], 
    isOwner: boolean, 
    onEdit: (p: Product) => void, 
    onAdd: () => void 
}> = ({ products, isOwner, onEdit, onAdd }) => {
    const scrollRef = useRef<HTMLDivElement>(null);

    const scroll = (direction: 'left' | 'right') => {
        if (scrollRef.current) {
            const { current } = scrollRef;
            const scrollAmount = 300;
            if (direction === 'left') {
                current.scrollBy({ left: -scrollAmount, behavior: 'smooth' });
            } else {
                current.scrollBy({ left: scrollAmount, behavior: 'smooth' });
            }
        }
    };

    return (
        <div className="glass-card p-6 rounded-2xl mb-8 relative border-white/40 dark:border-white/5 shadow-xl">
            <div className="flex justify-between items-center mb-6">
                <div className="flex items-center gap-2">
                    <div className="bg-primary/10 p-2 rounded-lg text-primary">
                        <Package size={20} />
                    </div>
                    <h3 className="text-xl font-bold text-dark dark:text-white">
                        Featured Selection
                    </h3>
                </div>
                <div className="flex gap-2">
                    {isOwner && products.length < 5 && (
                        <button 
                            onClick={onAdd}
                            className="mr-2 flex items-center gap-1.5 text-xs font-bold bg-primary text-white px-3 py-1.5 rounded-lg hover:bg-red-600 transition-all shadow-md shadow-red-500/20"
                        >
                            <Plus size={14} /> Add Product
                        </button>
                    )}
                    <button onClick={() => scroll('left')} className="p-2 rounded-full border border-gray-100 dark:border-gray-700 hover:bg-gray-50 dark:hover:bg-gray-800 transition-colors">
                        <ChevronLeft size={20} className="text-gray-400" />
                    </button>
                    <button onClick={() => scroll('right')} className="p-2 rounded-full border border-gray-100 dark:border-gray-700 hover:bg-gray-50 dark:hover:bg-gray-800 transition-colors">
                        <ChevronRight size={20} className="text-gray-400" />
                    </button>
                </div>
            </div>

            {products.length > 0 ? (
                <div 
                    ref={scrollRef}
                    className="flex gap-5 overflow-x-auto no-scrollbar snap-x snap-mandatory pb-2"
                >
                    {products.map((product) => (
                        <div key={product.id} className="min-w-[260px] max-w-[260px] glass-card rounded-2xl overflow-hidden border-white/50 dark:border-white/5 snap-center shadow-lg hover:shadow-2xl transition-all duration-300 group relative">
                            <div className="h-44 relative overflow-hidden">
                                <img src={product.image} alt={product.name} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700" />
                                <div className="absolute top-3 left-3 flex flex-col gap-1.5">
                                    <div className="bg-white/90 dark:bg-black/80 backdrop-blur px-2.5 py-1 rounded-lg text-[11px] font-black text-dark dark:text-white shadow-sm border border-white/20">
                                        ₦{product.price.toLocaleString()}
                                    </div>
                                    {product.quantity <= 3 && (
                                        <div className="bg-orange-500/90 backdrop-blur px-2.5 py-1 rounded-lg text-[9px] font-black text-white uppercase tracking-wider animate-pulse">
                                            Only {product.quantity} Left
                                        </div>
                                    )}
                                </div>
                                {isOwner && (
                                    <button 
                                        onClick={() => onEdit(product)}
                                        className="absolute top-3 right-3 p-2 bg-white/90 dark:bg-slate-800/90 rounded-full text-primary opacity-0 group-hover:opacity-100 transition-opacity shadow-lg"
                                    >
                                        <Edit3 size={14} />
                                    </button>
                                )}
                            </div>
                            <div className="p-4 bg-white/50 dark:bg-transparent">
                                <h4 className="font-bold text-dark dark:text-white text-sm mb-3 truncate">{product.name}</h4>
                                <button className="w-full bg-dark dark:bg-white dark:text-dark text-white py-2 rounded-xl text-xs font-bold flex items-center justify-center gap-2 hover:bg-primary dark:hover:bg-primary dark:hover:text-white transition-all transform active:scale-95">
                                    <ShoppingCart size={14} /> Contact to Buy
                                </button>
                            </div>
                        </div>
                    ))}
                </div>
            ) : (
                <div className="py-12 text-center border-2 border-dashed border-gray-100 dark:border-gray-800 rounded-2xl">
                    <Package className="mx-auto text-gray-200 dark:text-gray-700 mb-2" size={48} />
                    <p className="text-gray-400 text-sm font-medium">No products showcased yet.</p>
                    {isOwner && (
                        <button onClick={onAdd} className="mt-4 text-primary font-bold hover:underline flex items-center gap-1 mx-auto">
                            <Plus size={16} /> Click here to add your first product
                        </button>
                    )}
                </div>
            )}
        </div>
    );
};

const BusinessDetail: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const { user } = useAuth();
  const [showShareMenu, setShowShareMenu] = useState(false);
  const [copied, setCopied] = useState(false);

  const [sortBy, setSortBy] = useState<'recent' | 'highest' | 'lowest' | 'helpful'>('recent');
  const [filterRating, setFilterRating] = useState<number | 'all'>('all');

  const business = MOCK_BUSINESSES.find(b => b.id === id);
  const [isActiveListing, setIsActiveListing] = useState(false);

  // Product Modal State
  const [isProductModalOpen, setIsProductModalOpen] = useState(false);
  const [editingProduct, setEditingProduct] = useState<Product | null>(null);
  const [productFormData, setProductFormData] = useState({ name: '', price: '', quantity: '', image: '' });
  const [localProducts, setLocalProducts] = useState<Product[]>([]);

  useEffect(() => {
      if (business) {
          analyticsService.trackEvent('view', business.id, user?.id);
          setIsActiveListing(business.status === 'active');
          setLocalProducts(business.products || []);
      }
  }, [business, user]);

  const [reviews, setReviews] = useState<Review[]>(
      MOCK_REVIEWS.filter(r => r.businessId === id)
  );

  if (!business) {
    return <div className="text-center py-20 text-dark dark:text-white font-bold">Business not found</div>;
  }

  const handleOpenProductModal = (product?: Product) => {
      if (product) {
          setEditingProduct(product);
          setProductFormData({ 
              name: product.name, 
              price: product.price.toString(), 
              quantity: product.quantity.toString(), 
              image: product.image 
          });
      } else {
          setEditingProduct(null);
          setProductFormData({ name: '', price: '', quantity: '', image: '' });
      }
      setIsProductModalOpen(true);
  };

  const handleSaveProduct = (e: React.FormEvent) => {
      e.preventDefault();
      const productData: Product = {
          id: editingProduct?.id || Date.now().toString(),
          name: productFormData.name,
          price: parseInt(productFormData.price),
          quantity: parseInt(productFormData.quantity),
          image: productFormData.image || 'https://picsum.photos/seed/prod/400/300'
      };

      if (editingProduct) {
          setLocalProducts(localProducts.map(p => p.id === productData.id ? productData : p));
      } else {
          setLocalProducts([...localProducts, productData]);
      }
      setIsProductModalOpen(false);
  };

  const handleDeleteProduct = () => {
      if (editingProduct && window.confirm('Permanently delete this product?')) {
          setLocalProducts(localProducts.filter(p => p.id !== editingProduct.id));
          setIsProductModalOpen(false);
      }
  };

  const getProcessedReviews = () => {
      let filtered = reviews;
      if (filterRating !== 'all') {
          filtered = filtered.filter(r => Math.floor(r.rating) === filterRating);
      }
      return filtered.sort((a, b) => {
          if (sortBy === 'highest') return b.rating - a.rating;
          if (sortBy === 'lowest') return a.rating - b.rating;
          if (sortBy === 'helpful') return b.helpfulCount - a.helpfulCount;
          return new Date(b.date).getTime() - new Date(a.date).getTime();
      });
  };

  const processedReviews = getProcessedReviews();

  const handleReviewSubmit = (rating: number, text: string, photos: File[]) => {
      const newReview: Review = {
          id: Math.random().toString(),
          businessId: business.id,
          userId: user?.id || 'guest',
          userName: user?.name || 'Guest User',
          userImage: user?.image || 'https://ui-avatars.com/api/?name=Guest',
          rating: rating,
          date: new Date().toISOString(),
          text: text,
          helpfulCount: 0,
          photos: [],
          status: 'active'
      };
      setReviews([newReview, ...reviews]);
      if (business.ownerId) {
          notificationService.notifyReview(business.ownerId, business.name, newReview.userName);
      }
  };

  const handleVendorReply = (reviewId: string, text: string) => {
      setReviews(prevReviews => prevReviews.map(r => 
          r.id === reviewId ? { ...r, reply: { text, date: new Date().toISOString() }, isRead: true } : r
      ));
  };

  const handleReportReview = (reviewId: string) => {
      setReviews(prevReviews => prevReviews.map(r => 
          r.id === reviewId ? { ...r, status: 'flagged' } : r
      ));
  };

  const isOwner = user?.id === business.ownerId || user?.role === 'admin';

  return (
    <div className="pb-20" onClick={() => showShareMenu && setShowShareMenu(false)}>
      {/* Header Profile Section */}
      <div className="bg-white dark:bg-slate-900 border-b border-gray-100 dark:border-gray-800 transition-colors">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
          <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
             <div className="flex items-center gap-4 md:gap-6">
                {business.logo && (
                    <img 
                        src={business.logo} 
                        alt={`${business.name} logo`} 
                        className="w-20 h-20 md:w-24 md:h-24 rounded-full border-4 border-white dark:border-gray-800 shadow-lg object-cover bg-white dark:bg-gray-800 flex-shrink-0" 
                    />
                )}
                <div>
                    <div className="flex items-center gap-3 mb-2 flex-wrap">
                        <h1 className="text-2xl md:text-3xl font-bold text-dark dark:text-white">{business.name}</h1>
                        <span className="bg-green-500 text-white text-xs font-bold px-2 py-1 rounded-md">{business.rating}</span>
                        {!isActiveListing && isOwner && (
                            <span className="bg-red-100 text-red-600 text-xs font-bold px-2 py-1 rounded-md border border-red-200">Inactive</span>
                        )}
                    </div>
                    <div className="flex flex-wrap items-center gap-4 text-sm text-graytext dark:text-gray-400">
                    <div className="flex items-center gap-1">
                        {[...Array(5)].map((_, i) => (
                            <Star key={i} size={14} className={`${i < Math.floor(business.rating) ? 'text-yellow-400 fill-yellow-400' : 'text-gray-300 dark:text-gray-600'}`} />
                        ))}
                        <span className="ml-1">({business.reviewCount} reviews)</span>
                    </div>
                    <div className="flex items-center gap-1">
                        <MapPin size={14} className="text-primary" />
                        {business.location}
                    </div>
                    <div className="flex items-center gap-1">
                        <span className="text-primary font-semibold">{business.priceRange}</span>
                    </div>
                    </div>
                </div>
             </div>
             <div className="flex gap-3 relative z-20 w-full md:w-auto mt-4 md:mt-0 flex-wrap">
                {isOwner && (
                    <button className="flex-1 md:flex-none flex items-center justify-center gap-2 px-4 py-2 bg-primary text-white rounded-lg hover:bg-red-600 font-medium transition-colors shadow-lg shadow-red-500/20">
                        <Edit3 size={18} /> Manage Business
                    </button>
                )}
                <button className="flex-1 md:flex-none flex items-center justify-center gap-2 px-4 py-2 bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-lg hover:bg-gray-50 dark:hover:bg-gray-700 text-dark dark:text-white font-medium transition-colors">
                    <Heart size={18} /> Save
                </button>
             </div>
          </div>
        </div>
      </div>

      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-2 space-y-8">
            {/* Cover Image */}
            <div className="rounded-2xl overflow-hidden shadow-lg h-64 sm:h-96 relative group">
                <img src={business.image} alt={business.name} loading="lazy" className={`w-full h-full object-cover transform group-hover:scale-105 transition-transform duration-700`} />
                <div className="absolute inset-0 bg-gradient-to-t from-black/50 to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-300"></div>
            </div>

            {/* About Section */}
            <div className="glass-card p-6 rounded-2xl">
                <h3 className="text-xl font-bold text-dark dark:text-white mb-4">About Business</h3>
                <p className="text-graytext dark:text-gray-300 leading-relaxed mb-6 text-sm sm:text-base">
                    {business.description}
                </p>
                <h4 className="font-semibold text-dark dark:text-white mb-3">Amenities</h4>
                <div className="grid grid-cols-2 md:grid-cols-3 gap-3">
                    {business.tags.map((tag, i) => (
                        <div key={i} className="flex items-center gap-2 text-graytext dark:text-gray-300 text-sm">
                            <CheckCircle size={16} className="text-primary" />
                            {tag}
                        </div>
                    ))}
                </div>
            </div>

            {/* PRODUCT CAROUSEL INTEGRATION */}
            <ProductCarousel 
                products={localProducts} 
                isOwner={isOwner} 
                onEdit={handleOpenProductModal}
                onAdd={() => handleOpenProductModal()}
            />

            {/* Reviews Section */}
            <div id="reviews">
                <h3 className="text-2xl font-bold text-dark dark:text-white mb-6 flex items-center gap-2">
                    Reviews <span className="text-gray-400 text-lg font-medium">({reviews.length})</span>
                </h3>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-8">
                    <div className="glass-card p-6 rounded-2xl flex flex-col items-center justify-center text-center">
                        <div className="text-5xl font-black text-dark dark:text-white mb-2">{business.rating}</div>
                        <div className="flex gap-1 mb-2">
                             {[...Array(5)].map((_, i) => (
                                <Star key={i} size={20} className={`${i < Math.floor(business.rating) ? 'fill-yellow-400 text-yellow-400' : 'text-gray-300 dark:text-gray-600'}`} />
                             ))}
                        </div>
                        <p className="text-gray-500 text-sm">Overall Rating</p>
                    </div>
                    <RatingBreakdown reviews={reviews} />
                </div>
                {user ? (
                    <ReviewForm user={user} onSubmit={handleReviewSubmit} />
                ) : (
                    <div className="bg-gray-50 dark:bg-gray-800 p-6 rounded-2xl text-center mb-8 border border-gray-100 dark:border-gray-700">
                        <p className="text-dark dark:text-white font-medium mb-3">Share your experience with this business</p>
                        <Link to="/login" className="inline-block bg-white dark:bg-gray-700 border border-gray-200 dark:border-gray-600 px-6 py-2.5 rounded-xl text-primary font-bold shadow-sm hover:shadow-md transition-all">
